":{"page":364,"x":64,"y":157,"width":726,"height":131,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[{"figure":425,"page":364,"x":545,"y":465,"width":210,"height":180,"sourceWidth":828,"sourceHeight":1097}]},{"task":"1410","source_page":364,"condition":"Постройте границу круга, площадь которого равна: а) площади кольца между двумя данными концентрическими окружностями; 0) площади данного полукруга; в) площади данного кругового сектора, ограниченного дугой в 60°.","condition_normalized":"постройте границу круга,площадь которого равна:а) площади кольца между двумя данными концентрическими окружностями;0) площади данного полукруга;в) площади данного кругового сектора,ограниченного дугой в 60°.","ocr_confidence":93,"has_diagram":false,"source_region":{"page":364,"x":64,"y":275,"width":726,"height":220,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1411","source_page":364,"condition":"При данном движении # точка А отображается в точку В, а точка В — в точку A. Докажите, что g — центральная симметрия или осевая симметрия.","condition_normalized":"при данном движении # точка а отображается в точку в,а точка в - в точку a.докажите,что g - центральная симметрия или осевая симметрия.","ocr_confidence":90,"has_diagram":false,"source_region":{"page":364,"x":64,"y":482,"width":726,"height":90,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1412","source_page":364,"condition":"Даны два равных отрезка AB и A₁B₁. Докажите, что существуют два и только два движения, при которых точки A и B отображаются соответственно в точки A₁ и B₁.","condition_normalized":"даны два равных отрезка ab и a1b1.докажите,что существуют два и только два движения,при которых точки a и b отображаются соответственно в точки a1 и b1.","ocr_confidence":87,"has_diagram":false,"source_region":{"page":364,"x":64,"y":559,"width":726,"height":92,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1413","source_page":364,"condition":"Докажите, что два параллелограмма равны, если диагонали и угол между ними одного параллелограмма соответственно равны диагоналям и углу между ними другого.","condition_normalized":"докажите,что два параллелограмма равны,если диагонали и угол между ними одного параллелограмма соответственно равны диагоналям и углу между ними другого.","ocr_confidence":93,"has_diagram":false,"source_region":{"page":364,"x":64,"y":638,"width":726,"height":73,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1414","source_page":364,"condition":"Докажите, что две трапеции равны, если основания и боковые стороны одной трапеции соответственно равны основаниям и боковым сторонам другой.","condition_normalized":"докажите,что две трапеции равны,если основания и боковые стороны одной трапеции соответственно равны основаниям и боковым сторонам другой.","ocr_confidence":95,"has_diagram":false,"source_region":{"page":364,"x":64,"y":698,"width":726,"height":72,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1415","source_page":364,"condition":"Докажите, что два треугольника равны, если две неравные стороны и разность противолежащих им углов одного треугольника соответственно равны двум сторонам и разности противолежащих им углов другого.","condition_normalized":"докажите,что два треугольника равны,если две неравные стороны и разность противолежащих им углов одного треугольника соответственно равны двум сторонам и разности противолежащих им углов другого.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":364,"x":64,"y":757,"width":726,"height":91,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1416","source_page":364,"condition":"Вершины одного параллелограмма лежат соответственно на сторонах другого параллелограмма. Докажите, что точки пересечения диагоналей этих параллелограммов совпадают.","condition_normalized":"вершины одного параллелограмма лежат соответственно на сторонах другого параллелограмма.докажите,что точки пересечения диагоналей этих параллелограммов совпадают.","ocr_confidence":93,"has_diagram":false,"source_region":{"page":364,"x":64,"y":835,"width":726,"height":72,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1417","source_page":364,"condition":"Даны две окружности и прямая. Постройте правильный треугольник так, чтобы две вершины лежали соответственно на данных окружностях, а высота, проведённая из третьей вертпины, — на данной прямой.","condition_normalized":"даны две окружности и прямая.постройте правильный треугольник так,чтобы две вершины лежали соответственно на данных окружностях,а высота,проведенная из третьей вертпины,- на данной прямой.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":364,"x":64,"y":894,"width":726,"height":101,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1418","source_page":365,"condition":"На стороне угла АОВ с недоступной вершиной дана точка М. Постройте отрезок, равный отрезку ОМ.","condition_normalized":"на стороне угла аов с недоступной вершиной дана точка м.постройте отрезок,равный отрезку ом.","ocr_confidence":95,"has_diagram":false,"source_region":{"page":365,"x":94,"y":77,"width":696,"height":53,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1419","source_page":365,"condition":"Даны две пересекающиеся окружности. Постройте отрезок, концы которого лежат соответственно на данных окружностях, а его середина совпадает с одной из точек пересечения данных окружностей.","condition_normalized":"даны две пересекающиеся окружности.постройте отрезок,концы которого лежат соответственно на данных окружностях,а его середина совпадает с одной из точек пересечения данных окружностей.","ocr_confidence":95,"has_diagram":false,"source_region":{"page":365,"x":94,"y":117,"width":696,"height":91,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1420","source_page":365,"condition":"Постройте треугольник по трём медианам.","condition_normalized":"постройте треугольник по трем медианам.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":195,"width":696,"height":37,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1421","source_page":365,"condition":"Постройте трапецию, стороны которой соответственно равны данным отрезкам.","condition_normalized":"постройте трапецию,стороны которой соответственно равны данным отрезкам.","ocr_confidence":93,"has_diagram":false,"source_region":{"page":365,"x":94,"y":216,"width":696,"height":56,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1422","source_page":365,"condition":"Даны точки А и В и две пересекающиеся прямые с и d. Постройте параллелограмм ABCD так, чтобы вершины С и р лежали соответственно на прямых с и @.","condition_normalized":"даны точки а и в и две пересекающиеся прямые с и d.постройте параллелограмм abcd так,чтобы вершины с и р лежали соответственно на прямых с и @.","ocr_confidence":91,"has_diagram":false,"source_region":{"page":365,"x":94,"y":259,"width":696,"height":74,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1423","source_page":365,"condition":"Даны прямая, окружность и точка А, не лежащая на них. Постройте квадрат АВСР так, чтобы вершина В лежала на данной прямой, а вершина РВ) — на данной окружности.","condition_normalized":"даны прямая,окружность и точка а,не лежащая на них.постройте квадрат авср так,чтобы вершина в лежала на данной прямой,а вершина рв) - на данной окружности.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":320,"width":696,"height":124,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1424","source_page":365,"condition":"В данный сектор впишите квадрат так, чтобы две его смежные вершины принадлежали дуге АВ сектора, а две другие вершины — соответственно радиусам OA и OB.","condition_normalized":"в данный сектор впишите квадрат так,чтобы две его смежные вершины принадлежали дуге ав сектора,а две другие вершины - соответственно радиусам oa и ob.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":431,"width":696,"height":74,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1425","source_page":365,"condition":"Даны отрезки а, т, № {(m <n). Постройте прямоугольник ABCD так, чтобы АВ = а, BC: АС=т: п.","condition_normalized":"даны отрезки а,т,no {(m <n).постройте прямоугольник abcd так,чтобы ав = а,bc:ас=т:п.","ocr_confidence":77,"has_diagram":false,"source_region":{"page":365,"x":94,"y":493,"width":696,"height":55,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1426","source_page":365,"condition":"Даны отрезки a, т, п. Постройте ромб со стороной 2 HATE ли которого относятся как т: п.","condition_normalized":"даны отрезки a,т,п.постройте ромб со стороной 2 hate ли которого относятся как т:п.","ocr_confidence":79,"has_diagram":false,"source_region":{"page":365,"x":94,"y":535,"width":696,"height":56,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1427","source_page":365,"condition":"В данный равносторонний треугольник впишите другой равносторонний треугольник так, чтобы его стороны были перпендикулярны к сторонам данного.","condition_normalized":"в данный равносторонний треугольник впишите другой равносторонний треугольник так,чтобы его стороны были перпендикулярны к сторонам данного.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":578,"width":696,"height":75,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1428","source_page":365,"condition":"В угол вписаны две окружности, одна из которых касается сторон угла в точках М и №, а другая — в точках Р и @. Докажите, что эти окружности на прямой ME отсекают равные хорды.","condition_normalized":"в угол вписаны две окружности,одна из которых касается сторон угла в точках м и no,а другая - в точках р и @.докажите,что эти окружности на прямой me отсекают равные хорды.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":640,"width":696,"height":92,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1429","source_page":365,"condition":"Дана окружность и точка А вне этой окружности. Через точку А провести секущую к окружности так, чтобы внешняя часть секущей была в 2 раза больше внутренней.","condition_normalized":"дана окружность и точка а вне этой окружности.через точку а провести секущую к окружности так,чтобы внешняя часть секущей была в 2 раза больше внутренней.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":719,"width":696,"height":75,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1430","source_page":365,"condition":"Отрезок BD — биссектриса треугольника АВС. Докажите, что Вр*= AB ВС - ADDC.","condition_normalized":"отрезок bd - биссектриса треугольника авс.докажите,что вр*= ab вс - addc.","ocr_confidence":79,"has_diagram":false,"source_region":{"page":365,"x":94,"y":781,"width":696,"height":55,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]},{"task":"1431","source_page":365,"condition":"Пользуясь результатом задачи 909, применяя гомотетию, докажите, что для неравностороннего треугольника основания высот, середины сторон и середины отрезков высот, заключённых между вершинами треугольника и его ортоцентром, принадлежат одной окружности (окружности девяти точек). Центр этой окружности лежит на прямой Эйлера, а радиус равен половине радиуса описанной окружности данного треугольника.","condition_normalized":"пользуясь результатом задачи 909,применяя гомотетию,докажите,что для неравностороннего треугольника основания высот,середины сторон и середины отрезков высот,заключенных между вершинами треугольника и его ортоцентром,принадлежат одной окружности (окружности девяти точек).центр этой окружности лежит на прямой эйлера,а радиус равен половине радиуса описанной окружности данного треугольника.","ocr_confidence":94,"has_diagram":false,"source_region":{"page":365,"x":94,"y":823,"width":696,"height":172,"sourceWidth":827,"sourceHeight":1100},"diagram_regions":[]}]$geometry_tasks$::jsonb) as source_task(
    task text,
    source_page integer,
    condition text,
    condition_normalized text,
    ocr_confidence smallint,
    has_diagram boolean,
    source_region jsonb,
    diagram_regions jsonb
  )
)
insert into public.verified_homework_tasks (
  textbook_id,
  textbook_edition,
  source_url,
  task,
  source_page,
  condition,
  condition_normalized,
  source_region,
  ocr_confidence,
  has_diagram,
  diagram_regions
)
select
  'geometry',
  '14-е издание, Просвещение, 2023',
  '/textbooks/geometry-7-9-atanasyan.pdf',
  source_task.task,
  source_task.source_page,
  source_task.condition,
  source_task.condition_normalized,
  source_task.source_region,
  source_task.ocr_confidence,
  source_task.has_diagram,
  source_task.diagram_regions
from source_tasks as source_task
on conflict (textbook_id, textbook_edition, source_url, task)
do update set
  source_page = excluded.source_page,
  condition = excluded.condition,
  condition_normalized = excluded.condition_normalized,
  source_region = excluded.source_region,
  ocr_confidence = excluded.ocr_confidence,
  has_diagram = excluded.has_diagram,
  diagram_regions = excluded.diagram_regions;

drop function if exists public.get_verified_homework_task(text, text, text, text);

create function public.get_verified_homework_task(
  p_textbook_id text,
  p_edition text,
  p_source_url text,
  p_task text
)
returns table (
  condition text,
  condition_normalized text,
  source_url text,
  source_page integer,
  source_region jsonb,
  diagram_regions jsonb,
  ocr_confidence smallint,
  has_diagram boolean
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    verified.condition,
    verified.condition_normalized,
    verified.source_url,
    verified.source_page,
    verified.source_region,
    verified.diagram_regions,
    verified.ocr_confidence,
    verified.has_diagram
  from public.verified_homework_tasks as verified
  where char_length(coalesce(p_textbook_id, '')) between 1 and 150
    and char_length(coalesce(p_edition, '')) between 1 and 200
    and char_length(coalesce(p_source_url, '')) between 1 and 500
    and p_task ~ '^[0-9]{1,4}$'
    and verified.textbook_id = p_textbook_id
    and verified.textbook_edition = p_edition
    and verified.source_url = p_source_url
    and verified.task = p_task
  limit 1
$$;

revoke all on function public.get_verified_homework_task(text, text, text, text)
  from public, anon, authenticated;
grant execute on function public.get_verified_homework_task(text, text, text, text)
  to anon, authenticated;

analyze public.verified_homework_tasks;
